using System;
using System.IO;
using System.Text;
using UnityEngine;

namespace Game.UI.CabDisplays
{
    /// <summary>
    /// Navigation map of one region (KNAV v1, generated by <c>tools/ui/build_nav_map.py</c> from the region's road graph,
    /// building footprints and start route; Resources/CabDisplay/Nav/&lt;region&gt;.bytes). Region-local metres
    /// (x = east, y = north). Loaded once; drawing reads the flat arrays only (no allocation).
    /// Data: OpenStreetMap contributors (ODbL 1.0) and GUGiK BDOT10k - see docs/LICENSES.md (nav-map-data).
    /// </summary>
    public sealed class NavMapData
    {
        public const string ResourceFolder = "CabDisplay/Nav/";

        public string[] Names = Array.Empty<string>();
        public Vector2 Min, Max;

        // Roads: polyline i spans RoadPoints[RoadStart[i] .. RoadStart[i + 1]).
        public byte[] RoadClass = Array.Empty<byte>();
        public byte[] RoadFlags = Array.Empty<byte>();
        public float[] RoadWidth = Array.Empty<float>();
        public ushort[] RoadName = Array.Empty<ushort>();
        public int[] RoadStart = Array.Empty<int>();
        public Vector2[] RoadPoints = Array.Empty<Vector2>();
        /// <summary>Bounding box per road (min.x, min.y, max.x, max.y) for culling.</summary>
        public Vector4[] RoadBounds = Array.Empty<Vector4>();

        // Buildings: triangle list over BuildingPoints (indices already offset), bounds per building.
        public Vector2[] BuildingPoints = Array.Empty<Vector2>();
        public int[] BuildingTriStart = Array.Empty<int>();
        public int[] BuildingTris = Array.Empty<int>();
        public Vector4[] BuildingBounds = Array.Empty<Vector4>();

        // Route (the start route G3): points, cumulative distance, street name index, speed limit.
        public Vector2[] Route = Array.Empty<Vector2>();
        public float[] RouteS = Array.Empty<float>();
        public ushort[] RouteName = Array.Empty<ushort>();
        public ushort[] RouteLimit = Array.Empty<ushort>();

        public int RoadCount => RoadClass.Length;
        public int BuildingCount => BuildingTriStart.Length - (BuildingTriStart.Length > 0 ? 1 : 0);
        public float RouteLength => RouteS.Length > 0 ? RouteS[RouteS.Length - 1] : 0f;

        public static NavMapData Load(string regionId)
        {
            if (string.IsNullOrEmpty(regionId)) return null;
            var ta = Resources.Load<TextAsset>(ResourceFolder + regionId);
            if (ta == null) return null;
            try { return Parse(ta.bytes); }
            finally { Resources.UnloadAsset(ta); }
        }

        public static NavMapData Parse(byte[] bytes)
        {
            using var ms = new MemoryStream(bytes, false);
            using var r = new BinaryReader(ms, Encoding.UTF8);
            if (r.ReadByte() != 'K' || r.ReadByte() != 'N' || r.ReadByte() != 'A' || r.ReadByte() != 'V') throw new FormatException("not a KNAV file");
            int version = r.ReadUInt16();
            if (version != 1) throw new FormatException("KNAV version " + version + " unsupported");
            var d = new NavMapData();
            d.Min = new Vector2(r.ReadSingle(), r.ReadSingle());
            d.Max = new Vector2(r.ReadSingle(), r.ReadSingle());

            int nNames = r.ReadUInt16();
            d.Names = new string[nNames];
            for (int i = 0; i < nNames; i++) d.Names[i] = Encoding.UTF8.GetString(r.ReadBytes(r.ReadUInt16()));

            int nRoads = r.ReadUInt16();
            d.RoadClass = new byte[nRoads]; d.RoadFlags = new byte[nRoads]; d.RoadWidth = new float[nRoads];
            d.RoadName = new ushort[nRoads]; d.RoadStart = new int[nRoads + 1]; d.RoadBounds = new Vector4[nRoads];
            var pts = new System.Collections.Generic.List<Vector2>(4096);
            for (int i = 0; i < nRoads; i++)
            {
                d.RoadClass[i] = r.ReadByte(); d.RoadFlags[i] = r.ReadByte(); d.RoadWidth[i] = r.ReadSingle();
                d.RoadName[i] = r.ReadUInt16();
                int n = r.ReadUInt16();
                d.RoadStart[i] = pts.Count;
                var b = new Vector4(float.MaxValue, float.MaxValue, float.MinValue, float.MinValue);
                for (int k = 0; k < n; k++)
                {
                    var p = new Vector2(r.ReadSingle(), r.ReadSingle());
                    pts.Add(p);
                    b = new Vector4(Mathf.Min(b.x, p.x), Mathf.Min(b.y, p.y), Mathf.Max(b.z, p.x), Mathf.Max(b.w, p.y));
                }
                d.RoadBounds[i] = b;
            }
            d.RoadStart[nRoads] = pts.Count;
            d.RoadPoints = pts.ToArray();

            int nB = r.ReadUInt16();
            var bp = new System.Collections.Generic.List<Vector2>(8192);
            var bt = new System.Collections.Generic.List<int>(16384);
            d.BuildingTriStart = new int[nB + 1];
            d.BuildingBounds = new Vector4[nB];
            for (int i = 0; i < nB; i++)
            {
                int n = r.ReadUInt16(), baseIdx = bp.Count;
                var b = new Vector4(float.MaxValue, float.MaxValue, float.MinValue, float.MinValue);
                for (int k = 0; k < n; k++)
                {
                    var p = new Vector2(r.ReadSingle(), r.ReadSingle());
                    bp.Add(p);
                    b = new Vector4(Mathf.Min(b.x, p.x), Mathf.Min(b.y, p.y), Mathf.Max(b.z, p.x), Mathf.Max(b.w, p.y));
                }
                d.BuildingBounds[i] = b;
                d.BuildingTriStart[i] = bt.Count;
                int nt = r.ReadUInt16();
                for (int k = 0; k < nt * 3; k++)
                {
                    int idx = r.ReadUInt16();
                    if (idx >= n) throw new FormatException("building triangle index out of range");
                    bt.Add(baseIdx + idx);
                }
            }
            d.BuildingTriStart[nB] = bt.Count;
            d.BuildingPoints = bp.ToArray();
            d.BuildingTris = bt.ToArray();

            int nR = (int)r.ReadUInt32();
            d.Route = new Vector2[nR]; d.RouteS = new float[nR]; d.RouteName = new ushort[nR]; d.RouteLimit = new ushort[nR];
            for (int i = 0; i < nR; i++)
            {
                d.Route[i] = new Vector2(r.ReadSingle(), r.ReadSingle());
                d.RouteName[i] = r.ReadUInt16();
                d.RouteLimit[i] = r.ReadUInt16();
                d.RouteS[i] = i == 0 ? 0f : d.RouteS[i - 1] + Vector2.Distance(d.Route[i - 1], d.Route[i]);
            }
            if (ms.Position != ms.Length) throw new FormatException("KNAV trailing bytes");
            return d;
        }

        /// <summary>Closest route station to <paramref name="p"/> searched near <paramref name="hint"/> (index), or globally when hint &lt; 0.</summary>
        public int NearestRouteIndex(Vector2 p, int hint, out float distance)
        {
            int n = Route.Length;
            distance = float.MaxValue;
            if (n == 0) return -1;
            int a = 0, b = n - 1;
            if (hint >= 0) { a = Mathf.Max(0, hint - 40); b = Mathf.Min(n - 1, hint + 120); }
            int best = -1;
            for (int i = a; i <= b; i++)
            {
                float d = (Route[i] - p).sqrMagnitude;
                if (d < distance) { distance = d; best = i; }
            }
            distance = Mathf.Sqrt(distance);
            return best;
        }
    }
}
